const [open, setOpen] = useState(false);

async function handleSave() {
  await save();
  setOpen(true);
}

<Popup open={open} onOpenChange={setOpen} role="status" alignment="bottomStart" content={<span>Saved</span>}>
  <Button onClick={handleSave}>Save</Button>
</Popup>

const [channels, setChannels] = useState(['email']);

<CheckboxGroup
  label="Send matter updates by"
  value={channels}
  onValueChange={setChannels}
  options={[
    { value: 'email', label: 'Email' },
    { value: 'sms', label: 'SMS' },
    { value: 'in-app', label: 'In-app' },
  ]}
/>

const [isFavorite, setIsFavorite] = useState(false);

<ToggleIconButton aria-label="Favorite" isSelected={isFavorite} onClick={() => setIsFavorite(!isFavorite)}>
  {isFavorite ? <StarStarredIcon /> : <StarUnstarredIcon />}
</ToggleIconButton>

const [scope, setScope] = useState('matters');

<Chip
  mode="search"
  label="Matters"
  isSelected={scope === 'matters'}
  onSelectedChange={() => setScope('matters')}
/>

const [scopes, setScopes] = useState(() => new Set(['matters']));
const toggle = (id) =>
  setScopes((current) => {
    const next = new Set(current);
    next.has(id) ? next.delete(id) : next.add(id);
    return next;
  });

<ChipGroup size="sm" aria-label="Search scopes">
  {options.map((option) => (
    <Chip
      key={option.id}
      mode="search"
      label={option.label}
      elemBefore={<SearchIcon decorative />}
      isSelected={scopes.has(option.id)}
      onSelectedChange={() => toggle(option.id)}
    />
  ))}
</ChipGroup>

